import{_ as e,o,c as r,a2 as t}from"./chunks/framework.1C62pOns.js";const s="/pro-agent-hub-installer/capturas/pt/mcp-externo.png",i="/pro-agent-hub-installer/capturas/pt/mcp-proprio.png",b=JSON.parse('{"title":"Serviços MCP","description":"","frontmatter":{},"headers":[],"relativePath":"pt/interface/mcp.md","filePath":"pt/interface/mcp.md","lastUpdated":1787856241000}'),n={name:"pt/interface/mcp.md"};function p(c,a,d,u,l,m){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="servicos-mcp" tabindex="-1">Serviços MCP <a class="header-anchor" href="#servicos-mcp" aria-label="Permalink to &quot;Serviços MCP&quot;">​</a></h1><p><strong>MCP</strong> (Model Context Protocol) é o padrão pelo qual um agente ganha ferramentas que não vieram embutidas. A tela cadastra dois tipos bem diferentes de registro, e a escolha é feita na criação:</p><ul><li><strong>Externo</strong> — um servidor MCP de terceiro, que você consome por URL.</li><li><strong>Próprio</strong> — um servidor que <em>você</em> escreve aqui, e que a plataforma publica.</li></ul><h2 id="externo" tabindex="-1">Externo <a class="header-anchor" href="#externo" aria-label="Permalink to &quot;Externo&quot;">​</a></h2><p><img src="'+s+'" alt="mcp-externo"></p><p>Basta o transporte, a URL e o tempo limite. Nada é executado na sua instalação — a plataforma apenas fala com o endereço informado.</p><p>Depois de salvar, vincule o serviço a um agente na aba Ferramentas do agente.</p><h2 id="proprio" tabindex="-1">Próprio <a class="header-anchor" href="#proprio" aria-label="Permalink to &quot;Próprio&quot;">​</a></h2><p><img src="'+i+'" alt="mcp-proprio"></p><p>Aqui você escreve as ferramentas em Python e a plataforma sobe um servidor MCP para elas, num processo separado — um serviço MCP lento nunca prende uma requisição da API.</p><h3 id="aba-ferramentas" tabindex="-1">Aba Ferramentas <a class="header-anchor" href="#aba-ferramentas" aria-label="Permalink to &quot;Aba Ferramentas&quot;">​</a></h3><p>Cada função de topo vira uma ferramenta. <strong>Não escreva decorador nem rota</strong>: a plataforma envolve as funções e monta o <code>register_tools</code> sozinha. O nome, a assinatura e a docstring são o contrato que o modelo lê para decidir quando chamar.</p><p>O escopo traz <code>log()</code> e as operações de dados, sistema e integração — ver <a href="/pro-agent-hub-installer/pt/funcoes/mcp_tools">Serviço MCP</a>.</p><h3 id="aba-auxiliares" tabindex="-1">Aba Auxiliares <a class="header-anchor" href="#aba-auxiliares" aria-label="Permalink to &quot;Aba Auxiliares&quot;">​</a></h3><p>Código de apoio: <code>import</code>, constantes e funções compartilhadas. <strong>Nada daqui vira ferramenta</strong>, mesmo sendo função de topo. É a separação entre &quot;o que o modelo pode chamar&quot; e &quot;o que o seu código usa por dentro&quot;.</p><h3 id="aba-autenticacao" tabindex="-1">Aba Autenticação <a class="header-anchor" href="#aba-autenticacao" aria-label="Permalink to &quot;Aba Autenticação&quot;">​</a></h3><p>Três chaves, e vale entender o que cada uma abre:</p><ul><li><strong>Token fixo</strong> — um segredo que o chamador apresenta. É o que você entrega a um cliente fora da plataforma.</li><li><strong>Aceitar token de workflow</strong> — permite que workflows e planejadores da própria instalação chamem o serviço sem token próprio.</li><li><strong>Aceitar autenticação de usuário</strong> — permite que um usuário conectado chame, respeitando os grupos dele.</li></ul><p>Desligar as três deixa o serviço publicado e inalcançável.</p><h3 id="aba-versoes" tabindex="-1">Aba Versões <a class="header-anchor" href="#aba-versoes" aria-label="Permalink to &quot;Aba Versões&quot;">​</a></h3><p>Cada gravação guarda uma versão do código. Dá para comparar, restaurar e anotar uma observação em cada uma — o histórico é o que permite mexer num serviço que já está em uso sem medo.</p><h3 id="publicar" tabindex="-1">Publicar <a class="header-anchor" href="#publicar" aria-label="Permalink to &quot;Publicar&quot;">​</a></h3><p>O serviço próprio só entra no ar depois de publicado, e roda na <strong>porta</strong> do seu cadastro. Cada serviço tem a sua.</p><div class="warning custom-block"><p class="custom-block-title">A publicação é reconciliada, não instantânea</p><p>O processo que serve os MCPs compara periodicamente o que está no ar com o que está no banco. Depois de publicar, o endpoint aparece em segundos — não no mesmo instante do clique.</p></div><p><strong>Testar</strong> chama a ferramenta direto da tela, sem passar por agente. É o jeito de separar &quot;a ferramenta está errada&quot; de &quot;o modelo não a escolheu&quot;.</p>',25)])])}const g=e(n,[["render",p]]);export{b as __pageData,g as default};
